// Author-side policy: native observations and opaque candidates are the only
// inputs. No application workflow is compiled into the engine.
const key = fact => fact.ruleId.split('/').slice(-1)[0];
const unread = fact => fact.children?.some(child => child.visible === true && child.depth === 3 && child.type === 'Stack' && child.childCount === 0);
const reply = (state, targetRef = '', readAfterMs) => ({ state, ...(targetRef ? { targetRef } : {}),
  ...(readAfterMs === undefined ? {} : { readAfterMs }) });
const pendingRead = state => {
  const delays = [120, 240, 480, 800, 1200];
  const pass = Number.isSafeInteger(state.readPass) && state.readPass >= 0 ? state.readPass : 0;
  state.readPass = Math.min(pass + 1, delays.length - 1);
  return reply(state, '', delays[Math.min(pass, delays.length - 1)]);
};

export function onEvent(_ctx, event) {
  const o = event.observation, facts = o.facts || [];
  let s = event.state || {};
  if (o.scope === 'chat' && s.root !== o.rootKey) s = { root: o.rootKey, queue: [], done: [], pendingLong: '', triggered: '' };
  s.queue ||= []; s.done ||= [];
  if (event.kind === 'receipt') {
    const r = event.receipt, id = r.ruleId.split('/').slice(-1)[0];
    if (id.startsWith('assist-original-')) return reply(s);
    if (r.accepted) s.readPass = 0;
    if (id === 'assist-voice-menu' && r.accepted) s.triggered = r.scopeId;
    if (id === 'assist-voice-long-press') s.pendingLong = r.accepted ? r.scopeId : '';
    if (id === 'assist-voice-menu-confirm' && r.confirmed && s.pendingLong) {
      if (!s.done.includes(s.pendingLong)) s.done.push(s.pendingLong);
      s.pendingLong = '';
    }
    // The source's own outcome proof is a fact; other messages still require
    // their own transcript. A menu appearing is not a transcript result.
    if (id === 'assist-voice-menu' && r.confirmed && !s.done.includes(r.scopeId)) s.done.push(r.scopeId);
    return reply(s, '', r.accepted ? 0 : undefined);
  }
  const original = facts.find(f => key(f).startsWith('assist-original-') && f.targetRef);
  if (original) return reply(s, original.targetRef);
  const menu = facts.find(f => key(f) === 'assist-voice-menu-confirm' && f.targetRef);
  if (menu) return reply(s, menu.targetRef);
  if (o.scope !== 'chat' && !facts.some(f => ['assist-voice-menu','assist-voice-long-press'].includes(key(f)))) return reply(s);

  const voices = new Map();
  for (const f of facts) {
    if (!['assist-voice-menu','assist-voice-long-press'].includes(key(f))) continue;
    let v = voices.get(f.scopeId);
    if (!v) { v = { id: f.scopeId, top: f.top, satisfied: false, unread: false }; voices.set(f.scopeId, v); }
    v.satisfied ||= f.satisfied; v.unread ||= unread(f);
    if (key(f) === 'assist-voice-menu' && f.targetRef) v.inline = f;
    if (key(f) === 'assist-voice-long-press' && f.targetRef) v.long = f;
  }
  const beforeDone = s.done.length;
  for (const v of voices.values()) if (v.satisfied && !s.done.includes(v.id)) s.done.push(v.id);
  if (s.done.length !== beforeDone) s.readPass = 0;
  if (s.pendingLong && s.done.includes(s.pendingLong)) s.pendingLong = '';
  const pending = [...voices.values()].filter(v => !v.satisfied && !s.done.includes(v.id));
  s.queue = s.queue.filter(id => !s.done.includes(id));
  if (s.queue.length) {
    // Native auto-transcription may skip a read message between two unread
    // messages. Keep that read message pending; it is not a queue completion.
    // A missing/off-screen queue item is unknown, not successful: wait for a
    // real event instead of continually reading an invisible item.
    return s.queue.every(id => voices.has(id)) ? pendingRead(s) : reply(s);
  }
  if (s.pendingLong) return voices.has(s.pendingLong) ? pendingRead(s) : reply(s);
  const inline = pending.filter(v => v.inline && v.id !== s.triggered).sort((a, b) => a.top - b.top)[0];
  if (inline) {
    // Only the top message shows the inline entry in some WeChat versions.
    // The native empty Stack in the voice row is the unread dot in the captured
    // message structure. Read messages are retained for the second phase.
    s.queue = pending.filter(v => v.unread || v.id === inline.id).map(v => v.id);
    return reply(s, inline.inline.targetRef);
  }
  const fallback = pending.filter(v => v.long).sort((a, b) => b.top - a.top)[0];
  if (fallback) return reply(s, fallback.long.targetRef);
  // The recent-screenshot preview is mounted after its chat click. A frame
  // can still contain chat while the original-image control is being created.
  // Probe once for that real input, never turn the settled chat into a poll.
  if (o.scope === 'chat' && Number.isSafeInteger(o.inputEpoch) && o.inputEpoch > 0 &&
      (o.availableRules || []).some(id => key({ ruleId: id }) === 'assist-original-0') &&
      s.originalProbeEpoch !== o.inputEpoch) {
    s.originalProbeEpoch = o.inputEpoch;
    return reply(s, '', 120);
  }
  return reply(s);
}
